def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    if opp_def == 0:
        if n < 30:
            return 'C'
        if n >= 35:
            return 'D'
        if my_last == 'D':
            return 'C'
        return 'D'

    rate = float(opp_def) / float(n)

    opp_def3 = sum(1 for _, o in history[-3:] if o == 'D')
    opp_def5 = sum(1 for _, o in history[-5:] if o == 'D')
    opp_def10 = sum(1 for _, o in history[-10:] if o == 'D')

    consecutive = 0
    for _, o in reversed(history):
        if o == 'D':
            consecutive += 1
        else:
            break

    if rate >= 0.4 or opp_def10 >= 6 or consecutive >= 4:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_def5 >= 4 or consecutive >= 3 or rate >= 0.25:
                return 'D'
            if opp_def5 >= 3 and rng.random() < 0.5:
                return 'D'
            return 'C'
        else:
            if opp_def3 >= 3 or opp_def5 >= 4 or opp_def10 >= 5 or consecutive >= 3 or rate >= 0.2:
                return 'D'
            if rate < 0.05:
                return 'C'
            if rate < 0.15:
                if rng.random() < 0.78:
                    return 'C'
                return 'D'
            if rate < 0.3:
                if rng.random() < 0.45:
                    return 'C'
                return 'D'
            return 'D'

    if my_last == 'D':
        return 'C'

    if n >= 90 and rate < 0.03 and opp_def10 == 0 and opp_def <= 2:
        if rng.random() < 0.07:
            return 'D'
    return 'C'
